func TestError(t *testing.T) {
	require.Equal(t, "Decoder not found", ErrDecoderNotFound.Error())
	err1 := fmt.Errorf("test 1: %w", ErrDecoderNotFound)
	require.True(t, errors.Is(err1, ErrDecoderNotFound))
