	}
	if err = abuffersrcCtx.Initialize(nil); err != nil {
		return fmt.Errorf("initializing abuffersrc context failed: %w", err)
	}

	abuffersink := astiav.FindFilterByName("abuffersink")
	abuffersinkCtx, err := filterGraph.NewABuffersinkFilterContext(abuffersink, "out")
	if err != nil {
		return fmt.Errorf("creating abuffersink context failed: %w", err)
	}
	if err = abuffersinkCtx.SetSampleFmts([]astiav.SampleFormat{encCtx.SampleFormat()}); err != nil {
		return fmt.Errorf("setting sample fmts failed: %w", err)
	}
	if err = abuffersinkCtx.SetSampleRates([]int{encCtx.SampleRate()}); err != nil {
		return fmt.Errorf("setting sample rates failed: %w", err)
	}
	if err = abuffersinkCtx.SetChannelLayouts([]astiav.ChannelLayout{encCtx.ChannelLayout()}); err != nil {
		return fmt.Errorf("setting channel layouts failed: %w", err)
	}
	if err = abuffersinkCtx.Initialize(nil); err != nil {
		return fmt.Errorf("initializing abuffersink context failed: %w", err)
	}

	outputs := astiav.AllocFilterInOut()
	defer outputs.Free()
	outputs.SetName("in")
	outputs.SetFilterContext(abuffersrcCtx.FilterContext())
	outputs.SetPadIdx(0)

	inputs := astiav.AllocFilterInOut()
	defer inputs.Free()
	inputs.SetName("out")
	inputs.SetFilterContext(abuffersinkCtx.FilterContext())
	inputs.SetPadIdx(0)

	if err = filterGraph.Parse("anull", inputs, outputs); err != nil {
		return fmt.Errorf("parsing filter graph failed: %w", err)
	}
	if err = filterGraph.Configure(); err != nil {
		return fmt.Errorf("configuring filter graph failed: %w", err)
	}

	// 4. Start Processing
	inPkt := astiav.AllocPacket()
	defer inPkt.Free()
	frame := astiav.AllocFrame()
	defer frame.Free()

	processAndWrite := func(f *astiav.Frame) error {
		if err := abuffersrcCtx.AddFrame(f, astiav.NewBuffersrcFlags()); err != nil {
			return fmt.Errorf("adding frame to filter graph failed: %w", err)
		}
		for {
			err := abuffersinkCtx.GetFrame(frame, astiav.NewBuffersinkFlags())
			if err != nil {
				if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
					break
				}
				return fmt.Errorf("getting frame from filter graph failed: %w", err)
			}
			if err := encCtx.SendFrame(frame); err != nil {
				return fmt.Errorf("sending frame to encoder failed: %w", err)
			}
			frame.Unref()
			for {
				outPkt := astiav.AllocPacket()
				err := encCtx.ReceivePacket(outPkt)
				if err != nil {
					outPkt.Free()
					if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
						break
					}
					return fmt.Errorf("receiving packet from encoder failed: %w", err)
				}
				if err := writePacket(outPkt, encCtx, octx, ostream, ptsOffset); err != nil {
					outPkt.Free()
					return err
				}
				outPkt.Free()
			}
		}
		return nil
	}

	for {
		err = ictx.ReadFrame(inPkt)
		if err != nil {
			if errors.Is(err, astiav.ErrEof) {
				break
			}
			return fmt.Errorf("reading frame failed: %w", err)
		}
		if inPkt.StreamIndex() == istream.Index() {
			if err = decCtx.SendPacket(inPkt); err != nil {
				return fmt.Errorf("sending packet to decoder failed: %w", err)
			}
			inPkt.Unref()
			for {
				err = decCtx.ReceiveFrame(frame)
				if err != nil {
					if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
						break
					}
					return fmt.Errorf("receiving frame from decoder failed: %w", err)
				}
				if err = processAndWrite(frame); err != nil {
					return err
				}
				frame.Unref()
			}
		} else {
			inPkt.Unref()
		}
	}

	// 5. Flush pipeline
	if err = decCtx.SendPacket(nil); err != nil {
		return fmt.Errorf("flushing decoder failed: %w", err)
	}
	for {
		err = decCtx.ReceiveFrame(frame)
		if err != nil {
			if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
				break
			}
			return fmt.Errorf("receiving frame from decoder failed: %w", err)
		}
		if err = processAndWrite(frame); err != nil {
			return err
		}
		frame.Unref()
	}
	if err = processAndWrite(nil); err != nil {
		return err
	}

	return nil
}

func writePacket(pkt *astiav.Packet, encCtx *astiav.CodecContext, octx *astiav.FormatContext, ostream *astiav.Stream, ptsOffset int64) error {
	pkt.RescaleTs(encCtx.TimeBase(), ostream.TimeBase())
	pkt.SetPts(pkt.Pts() + ptsOffset)
	pkt.SetDts(pkt.Dts() + ptsOffset)
	pkt.SetStreamIndex(ostream.Index())
	pkt.SetPos(-1)

	if err := octx.WriteInterleavedFrame(pkt); err != nil {
		log.Printf("Warning: writing frame failed: %v\n", err)
	}
	return nil
}

